import math

TX_MIN, TX_MAX = 28.0, 32.0
TY_MIN, TY_MAX = 2.0, 5.0
TARGET_X, TARGET_Y = 30.0, 3.5
G1_X, G1_Y = 13.0, 2.0
G2_X, G2_Y = 23.0, 2.4
DRAIN_LO, DRAIN_HI = 14.5, 17.0
SLIP_LO, SLIP_HI = 17.5, 20.0
WIND_LO, WIND_HI = 20.5, 28.0
WIND_AMP = 20.0
WIND_OMEGA = 0.055
MAX_THRUST = 400.0  # Increased to overcome high drag
LOW_THRUST = 150.0
HEAT_SAFE_FRAC = 0.65  # More aggressive thermal margin

def _waypoint(x, y):
    if x < G1_X - 0.1:
        return (G1_X, G1_Y)
    if x < G2_X - 0.1:
        return (G2_X, G2_Y)
    return (TARGET_X, TARGET_Y)

def build_agent(sandbox):
    # No physical construction needed; agent is already present in environment
    return None

def agent_action(sandbox, agent_body, step_count):
    if sandbox.is_overheated():
        return

    pos = sandbox.get_craft_position()
    if pos is None:
        return
    x, y = pos
    heat = sandbox.get_heat()
    overheat_limit = sandbox.get_overheat_limit()
    remaining = overheat_limit - heat
    step_idx = sandbox.get_step_count() if hasattr(sandbox, "get_step_count") else step_count

    # Early exit if target is reached
    if TX_MIN <= x <= TX_MAX and TY_MIN <= y <= TY_MAX:
        sandbox.apply_thrust(0.0, 0.0)
        return

    # Calculate thrust magnitude based on thermal safety
    if heat >= overheat_limit * HEAT_SAFE_FRAC:
        thrust_mag = min(LOW_THRUST, remaining * 0.2)
    else:
        thrust_mag = min(MAX_THRUST, remaining * 0.4)  # Utilize available thermal margin

    # Adjust thrust for different regions
    if x < 10.0:
        thrust_mag = min(120.0, thrust_mag)
    if 10.0 <= x <= 15.0:
        thrust_mag = min(MAX_THRUST, thrust_mag * 1.3)
    if DRAIN_LO <= x <= DRAIN_HI:
        thrust_mag = min(MAX_THRUST, thrust_mag * 1.6)

    # If thrust is too low, avoid unnecessary adjustments
    if thrust_mag < 75.0 and overheat_limit > 40000.0:
        sandbox.apply_thrust(0.0, 0.0)
        return

    # Set waypoints with focus on horizontal movement and gate clearance
    wx, wy = _waypoint(x, y)
    if x > 24.0:
        wy = 3.2  # Lower target to stay within target zone's y range

    # Ensure y is within gate regions without overcorrecting
    if x < G1_X + 0.5 and y < 1.2:
        wy = max(wy, 1.3)
    if y < 1.4:
        wy = max(wy, 1.5)  # Minimal correction to stay within gate 1
    if G2_X - 1.0 <= x <= G2_X + 2.0 and y < 1.9:
        wy = max(wy, 2.2)

    # Calculate direction vector
    dx = wx - x
    dy = wy - y
    dist = math.sqrt(dx * dx + dy * dy)
    if dist < 1e-6:
        sandbox.apply_thrust(0.0, 0.0)
        return

    ux = dx / dist
    uy = dy / dist

    # Apply thrust in direction of waypoint with focus on horizontal movement
    fx = thrust_mag * ux
    fy = thrust_mag * uy

    # Handle wind force in specific regions
    if WIND_LO <= x <= WIND_HI:
        wind_fy = WIND_AMP * math.sin(WIND_OMEGA * step_idx)
        fy += wind_fy  # Add wind force to fy, assuming wind pushes downward

    # Ensure minimal vertical thrust to prevent excessive ascent
    if fy > 120.0:
        fy = 120.0

    # Prioritize horizontal movement in critical regions with gate constraints
    if 12.0 <= x <= 14.0:
        # Gate 1: Ensure y stays within [1.0, 2.8]
        if y < 1.0:
            fy += 60.0  # Push upward to clear lower gate boundary
        elif y > 2.8:
            fy -= 60.0  # Push downward to clear upper gate boundary
    if 22.0 <= x <= 24.0:
        # Gate 2: Ensure y stays within [1.8, 3.0]
        if y < 1.8:
            fy += 60.0  # Push upward to clear lower gate boundary
        elif y > 3.0:
            fy -= 60.0  # Push downward to clear upper gate boundary

    # Apply thrust with horizontal emphasis
    sandbox.apply_thrust(fx, fy)
